<template>
  <form :id="formId" class="flex flex-col w-full max-lg:px-0">
    <div class="flex flex-col gap-2">
      <Label>Upload File</Label>
      <div
        :class="
          cn(
            'flex gap-2 items-center border rounded-md pl-3 py-2 pr-8 relative w-full max-h-10 z-0',
            !isFileUploading && 'cursor-pointer'
          )
        "
        @click.stop.prevent="onImportFileClick"
      >
        <Button
          variant="ghost"
          type="button"
          size="sm"
          :disabled="isFileUploading"
          @click.stop.prevent="onImportFileClick"
          >Import File</Button
        >
        <Spinner v-if="isFileUploading" class="w-6 h-6 fill-foreground" />
        <span v-else class="truncate text-sm text-accent-foreground">{{ fileName ?? 'No file imported' }}</span>
        <span
          v-if="isRemovable && !isFileUploading"
          :class="cn('absolute z-20 end-0 inset-y-0 flex items-center justify-center px-2')"
        >
          <X class="size-4" @click.stop.prevent="clearInput" />
        </span>
      </div>
      <div v-if="isFileUploading" class="flex flex-col gap-1">
        <Progress :model-value="uploadProgress.percentage" class="h-2" />
        <span class="text-xs text-muted-foreground">
          {{ formatBytes(uploadProgress.loaded) }} / {{ formatBytes(uploadProgress.total) }} ({{
            uploadProgress.percentage
          }}%)
        </span>
      </div>
    </div>
    <FormItemWrapper name="file" class="hidden">
      <template #default="{ slots }">
        <input
          id="file"
          ref="fileInput"
          type="file"
          :accept="fileTypes.join(',')"
          class="hidden"
          @change="
            async (event: Event) => {
              slots.handleChange(event);
              await submit();
            }
          "
        />
      </template>
    </FormItemWrapper>
  </form>
</template>

<script lang="ts" setup>
import * as z from 'zod';
import { toTypedSchema } from '@vee-validate/zod';
import { useForm } from 'vee-validate';
import { X } from 'lucide-vue-next';
import { cn } from '@/lib/utils';
import { Spinner } from '~/assets/icons';

interface Props {
  formId: string;
  fileTypes?: string[];
  fileSizeLimit?: number; // in MB
  sizeUnit?: 'MB' | 'GB' | 'KB';
}

const props = withDefaults(defineProps<Props>(), {
  fileTypes: () => ['*'],
  fileSizeLimit: () => 50,
  sizeUnit: 'MB',
});

interface Emits {
  (e: 'onProcessData', event: { privateUrl: string; publicUrl: string; fileName: string } | null): void;
}

const emits = defineEmits<Emits>();

const isRemovable = ref<boolean>(false);
const fileName = ref<string | null>(null);
const isFileUploading = ref<boolean>(false);

const fileInput = ref<HTMLInputElement | null>(null);

const fileSizeConfigs = {
  KB: 1024,
  MB: 1024 * 1024,
  GB: 1024 * 1024 * 1024,
};

const UNITS = [
  { unit: 'GB', size: 1024 ** 3 },
  { unit: 'MB', size: 1024 ** 2 },
  { unit: 'KB', size: 1024 },
  { unit: 'B', size: 1 },
] as const;

function formatBytes(bytes: number, decimals = 1): string {
  if (!Number.isFinite(bytes) || bytes < 0) return '0 B';
  for (const { unit, size } of UNITS) {
    if (bytes >= size) return `${(bytes / size).toFixed(decimals)} ${unit}`;
  }
  return '0 B';
}

const inputSchema = toTypedSchema(
  z.object({
    file: z
      .instanceof(File)
      .optional()
      .refine(
        (file) => {
          if (!file || file.size <= props.fileSizeLimit * fileSizeConfigs[props.sizeUnit]) {
            return true;
          } else if (file.size > props.fileSizeLimit * fileSizeConfigs[props.sizeUnit]) {
            setFieldValue('file', undefined, false);
            return false;
          } else {
            return true;
          }
        },
        {
          message: `File size should not exceed ${props.fileSizeLimit} ${props.sizeUnit}`,
        }
      ),
  })
);

const { handleSubmit, resetForm, setFieldValue } = useForm({
  validationSchema: inputSchema,
});

const { uploadFileData, uploadProgress } = useUploadFile();

const submit = handleSubmit(async (values) => {
  if (values.file) {
    isRemovable.value = true;
    isFileUploading.value = true;
    await uploadFileData({ file: values.file })
      .then((response) => {
        if (values.file) fileName.value = values.file.name;
        emits('onProcessData', {
          privateUrl: response.private_url,
          publicUrl: response.public_url,
          fileName: values.file?.name || '',
        });
      })
      .catch((error) => {
        console.error('File upload failed:', error);
        showToastError(error, 'File upload failed');
        clearInput();
      })
      .finally(() => {
        isFileUploading.value = false;
      });
  } else {
    emits('onProcessData', null);
    isRemovable.value = false;
    fileName.value = null;
  }
});

function clearInput() {
  if (fileInput.value) {
    emits('onProcessData', null);
    resetForm();
    setFieldValue('file', undefined, false);
    if (fileInput.value) fileInput.value.value = '';
    fileName.value = null;
    isRemovable.value = false;
  }
}

function onImportFileClick() {
  if (isFileUploading.value) return;
  if (fileInput.value) fileInput.value.click();
}
</script>

<style lang="scss" scoped></style>
